"use strict";(self.webpackChunkml_seminars=self.webpackChunkml_seminars||[]).push([[769],{171:function(a){a.exports='<!DOCTYPE html>\n<html xmlns="http://www.w3.org/1999/xhtml" lang xml:lang>\n<head>\n  <meta charset="utf-8" />\n  <meta name="generator" content="pandoc" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=yes" />\n  <title>lab-08-clustering-em</title>\n  <style>\nhtml {\ncolor: #1a1a1a;\nbackground-color: #fdfdfd;\n}\nbody {\nmargin: 0 auto;\nmax-width: 36em;\npadding-left: 50px;\npadding-right: 50px;\npadding-top: 50px;\npadding-bottom: 50px;\nhyphens: auto;\noverflow-wrap: break-word;\ntext-rendering: optimizeLegibility;\nfont-kerning: normal;\n}\n@media (max-width: 600px) {\nbody {\nfont-size: 0.9em;\npadding: 12px;\n}\nh1 {\nfont-size: 1.8em;\n}\n}\n@media print {\nhtml {\nbackground-color: white;\n}\nbody {\nbackground-color: transparent;\ncolor: black;\nfont-size: 12pt;\n}\np, h2, h3 {\norphans: 3;\nwidows: 3;\n}\nh2, h3, h4 {\npage-break-after: avoid;\n}\n}\np {\nmargin: 1em 0;\n}\na {\ncolor: #1a1a1a;\n}\na:visited {\ncolor: #1a1a1a;\n}\nimg {\nmax-width: 100%;\n}\nsvg {\nheight: auto;\nmax-width: 100%;\n}\nh1, h2, h3, h4, h5, h6 {\nmargin-top: 1.4em;\n}\nh5, h6 {\nfont-size: 1em;\nfont-style: italic;\n}\nh6 {\nfont-weight: normal;\n}\nol, ul {\npadding-left: 1.7em;\nmargin-top: 1em;\n}\nli > ol, li > ul {\nmargin-top: 0;\n}\nblockquote {\nmargin: 1em 0 1em 1.7em;\npadding-left: 1em;\nborder-left: 2px solid #e6e6e6;\ncolor: #606060;\n}\ncode {\nfont-family: Menlo, Monaco, Consolas, \'Lucida Console\', monospace;\nfont-size: 85%;\nmargin: 0;\nhyphens: manual;\n}\npre {\nmargin: 1em 0;\noverflow: auto;\n}\npre code {\npadding: 0;\noverflow: visible;\noverflow-wrap: normal;\n}\n.sourceCode {\nbackground-color: transparent;\noverflow: visible;\n}\nhr {\nborder: none;\nborder-top: 1px solid #1a1a1a;\nheight: 1px;\nmargin: 1em 0;\n}\ntable {\nmargin: 1em 0;\nborder-collapse: collapse;\nwidth: 100%;\noverflow-x: auto;\ndisplay: block;\nfont-variant-numeric: lining-nums tabular-nums;\n}\ntable caption {\nmargin-bottom: 0.75em;\n}\ntbody {\nmargin-top: 0.5em;\nborder-top: 1px solid #1a1a1a;\nborder-bottom: 1px solid #1a1a1a;\n}\nth {\nborder-top: 1px solid #1a1a1a;\npadding: 0.25em 0.5em 0.25em 0.5em;\n}\ntd {\npadding: 0.125em 0.5em 0.25em 0.5em;\n}\nheader {\nmargin-bottom: 4em;\ntext-align: center;\n}\n#TOC li {\nlist-style: none;\n}\n#TOC ul {\npadding-left: 1.3em;\n}\n#TOC > ul {\npadding-left: 0;\n}\n#TOC a:not(:hover) {\ntext-decoration: none;\n}\ncode{white-space: pre-wrap;}\nspan.smallcaps{font-variant: small-caps;}\ndiv.columns{display: flex; gap: min(4vw, 1.5em);}\ndiv.column{flex: auto; overflow-x: auto;}\ndiv.hanging-indent{margin-left: 1.5em; text-indent: -1.5em;}\n\nul.task-list[class]{list-style: none;}\nul.task-list li input[type="checkbox"] {\nfont-size: inherit;\nwidth: 0.8em;\nmargin: 0 0.8em 0.2em -1.6em;\nvertical-align: middle;\n}\n\nhtml { -webkit-text-size-adjust: 100%; }\npre > code.sourceCode { white-space: pre; position: relative; }\npre > code.sourceCode > span { display: inline-block; line-height: 1.25; }\npre > code.sourceCode > span:empty { height: 1.2em; }\n.sourceCode { overflow: visible; }\ncode.sourceCode > span { color: inherit; text-decoration: inherit; }\ndiv.sourceCode { margin: 1em 0; }\npre.sourceCode { margin: 0; }\n@media screen {\ndiv.sourceCode { overflow: auto; }\n}\n@media print {\npre > code.sourceCode { white-space: pre-wrap; }\npre > code.sourceCode > span { text-indent: -5em; padding-left: 5em; }\n}\npre.numberSource code\n{ counter-reset: source-line 0; }\npre.numberSource code > span\n{ position: relative; left: -4em; counter-increment: source-line; }\npre.numberSource code > span > a:first-child::before\n{ content: counter(source-line);\nposition: relative; left: -1em; text-align: right; vertical-align: baseline;\nborder: none; display: inline-block;\n-webkit-touch-callout: none; -webkit-user-select: none;\n-khtml-user-select: none; -moz-user-select: none;\n-ms-user-select: none; user-select: none;\npadding: 0 4px; width: 4em;\ncolor: #aaaaaa;\n}\npre.numberSource { margin-left: 3em; border-left: 1px solid #aaaaaa; padding-left: 4px; }\ndiv.sourceCode\n{ background-color: #f8f8f8; }\n@media screen {\npre > code.sourceCode > span > a:first-child::before { text-decoration: underline; }\n}\ncode span.al { color: #ef2929; } \ncode span.an { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.at { color: #204a87; } \ncode span.bn { color: #0000cf; } \ncode span.cf { color: #204a87; font-weight: bold; } \ncode span.ch { color: #4e9a06; } \ncode span.cn { color: #8f5902; } \ncode span.co { color: #8f5902; font-style: italic; } \ncode span.cv { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.do { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.dt { color: #204a87; } \ncode span.dv { color: #0000cf; } \ncode span.er { color: #a40000; font-weight: bold; } \ncode span.ex { } \ncode span.fl { color: #0000cf; } \ncode span.fu { color: #204a87; font-weight: bold; } \ncode span.im { } \ncode span.in { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.kw { color: #204a87; font-weight: bold; } \ncode span.op { color: #ce5c00; font-weight: bold; } \ncode span.ot { color: #8f5902; } \ncode span.pp { color: #8f5902; font-style: italic; } \ncode span.sc { color: #ce5c00; font-weight: bold; } \ncode span.ss { color: #4e9a06; } \ncode span.st { color: #4e9a06; } \ncode span.va { color: #000000; } \ncode span.vs { color: #4e9a06; } \ncode span.wa { color: #8f5902; font-weight: bold; font-style: italic; } \n</style>\n</head>\n<body>\n<div id="cell000" class="cell markdown">\n<h1 id="лабораторная-работа-8-кластеризация-и-em-алгоритм">Лабораторная\nработа 8. Кластеризация и EM-алгоритм</h1>\n<p><strong>Курс «Машинное обучение», 4 курс, каф. ФН1</strong></p>\n<table>\n<colgroup>\n<col style="width: 50%" />\n<col style="width: 50%" />\n</colgroup>\n<tbody>\n<tr>\n<td>Место в курсе</td>\n<td>после лекции 7</td>\n</tr>\n<tr>\n<td>Опора на лекции</td>\n<td>лекция 7: функционал качества кластеризации и метод\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>K</mi><annotation encoding="application/x-tex">K</annotation></semantics></math>-средних\n(опр. 7.1), смеси распределений (опр. 7.4), EM-алгоритм (опр. 7.6) и его\nмонотонность (теорема 7.7), ответственности (опр. 7.8), иерархическая\nкластеризация и linkage (опр. 7.11)</td>\n</tr>\n<tr>\n<td>Трудоёмкость</td>\n<td>2 ч аудиторно + домашняя работа (3–4 ч)</td>\n</tr>\n</tbody>\n</table>\n<h2 id="цель-работы">Цель работы</h2>\n<p>Первое занятие курса без учителя. Понять, <strong>что именно</strong>\nоптимизирует каждый метод — и почему из этого сразу следует, какие\nструктуры данных он найти не сможет. Осознать, что «правильного» числа\nкластеров не существует, и научиться выбирать его осмысленно.</p>\n<h2 id="как-устроено-занятие">Как устроено занятие</h2>\n<p>Ноутбук разбирается в аудитории: код запускается и обсуждается по\nходу. Большая часть ячеек уже написана — их нужно <strong>прочитать и\nзапустить</strong>, разобравшись, что происходит и почему.</p>\n<p>Ячейки, помеченные <code># ✍ ЗАДАНИЕ НА СЕМИНАРЕ</code>, заполняются\nсамостоятельно прямо на занятии; их немного, и каждая занимает несколько\nстрок. Ячейки <strong>Вывод</strong> — тоже ваши: короткий ответ своими\nсловами на поставленный вопрос.</p>\n<p>Дома выполняется отдельный ноутбук <code>lab08_homework.ipynb</code>\n— там задания крупнее и делать их нужно самому.</p>\n<blockquote>\n<p><strong>Индивидуальный вариант.</strong> Датасет и набор методов\nвыдаются по вашему ФИО (см. ячейку ниже) — и на семинаре, и в домашней\nработе.</p>\n</blockquote>\n</div>\n<div id="cell001" class="cell markdown">\n<p>Кластеризация — задача <strong>обучения без учителя</strong>: ответов\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>y</mi><mi>i</mi></msub><annotation encoding="application/x-tex">y_i</annotation></semantics></math>\nнет. Это меняет всё, к чему мы привыкли: нет ни эмпирического риска\nотносительно истинных ответов, ни скользящего контроля в прежнем смысле,\nни однозначного критерия правильности. Поэтому здесь особенно важно\nпонимать устройство метода.</p>\n</div>\n<div id="cell002" class="cell code">\n<div class="sourceCode" id="cb1"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb1-1"><a href="#cb1-1" aria-hidden="true" tabindex="-1"></a><span class="co"># Служебная ячейка: импорты, стиль графиков, воспроизводимость.</span></span>\n<span id="cb1-2"><a href="#cb1-2" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> sys, pathlib, warnings</span>\n<span id="cb1-3"><a href="#cb1-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-4"><a href="#cb1-4" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> numpy <span class="im">as</span> np</span>\n<span id="cb1-5"><a href="#cb1-5" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> pandas <span class="im">as</span> pd</span>\n<span id="cb1-6"><a href="#cb1-6" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> matplotlib.pyplot <span class="im">as</span> plt</span>\n<span id="cb1-7"><a href="#cb1-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-8"><a href="#cb1-8" aria-hidden="true" tabindex="-1"></a>warnings.filterwarnings(<span class="st">&quot;ignore&quot;</span>, category<span class="op">=</span><span class="pp">FutureWarning</span>)</span>\n<span id="cb1-9"><a href="#cb1-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-10"><a href="#cb1-10" aria-hidden="true" tabindex="-1"></a><span class="co"># Модули практикума (variants.py, labdata.py) ищем рядом с ноутбуком.</span></span>\n<span id="cb1-11"><a href="#cb1-11" aria-hidden="true" tabindex="-1"></a><span class="co"># Если их нет -- значит, ноутбук открыт в Colab: скачиваем из репозитория курса.</span></span>\n<span id="cb1-12"><a href="#cb1-12" aria-hidden="true" tabindex="-1"></a>COURSE_FILES_URL <span class="op">=</span> <span class="st">&quot;https://raw.githubusercontent.com/sharipovaka/mltest1/main/notebooks&quot;</span></span>\n<span id="cb1-13"><a href="#cb1-13" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-14"><a href="#cb1-14" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-15"><a href="#cb1-15" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> _course_modules_dir():</span>\n<span id="cb1-16"><a href="#cb1-16" aria-hidden="true" tabindex="-1"></a>    here <span class="op">=</span> pathlib.Path.cwd()</span>\n<span id="cb1-17"><a href="#cb1-17" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> parent <span class="kw">in</span> [here, <span class="op">*</span>here.parents][:<span class="dv">4</span>]:</span>\n<span id="cb1-18"><a href="#cb1-18" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> (parent <span class="op">/</span> <span class="st">&quot;variants.py&quot;</span>).exists():</span>\n<span id="cb1-19"><a href="#cb1-19" aria-hidden="true" tabindex="-1"></a>            <span class="cf">return</span> <span class="bu">str</span>(parent)</span>\n<span id="cb1-20"><a href="#cb1-20" aria-hidden="true" tabindex="-1"></a>    <span class="im">import</span> urllib.request</span>\n<span id="cb1-21"><a href="#cb1-21" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> name <span class="kw">in</span> (<span class="st">&quot;variants.py&quot;</span>, <span class="st">&quot;labdata.py&quot;</span>):</span>\n<span id="cb1-22"><a href="#cb1-22" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> <span class="kw">not</span> pathlib.Path(name).exists():</span>\n<span id="cb1-23"><a href="#cb1-23" aria-hidden="true" tabindex="-1"></a>            urllib.request.urlretrieve(<span class="ss">f&quot;</span><span class="sc">{</span>COURSE_FILES_URL<span class="sc">}</span><span class="ss">/</span><span class="sc">{</span>name<span class="sc">}</span><span class="ss">&quot;</span>, name)</span>\n<span id="cb1-24"><a href="#cb1-24" aria-hidden="true" tabindex="-1"></a>            <span class="bu">print</span>(<span class="ss">f&quot;загружен </span><span class="sc">{</span>name<span class="sc">}</span><span class="ss"> из репозитория курса&quot;</span>)</span>\n<span id="cb1-25"><a href="#cb1-25" aria-hidden="true" tabindex="-1"></a>    <span class="cf">return</span> <span class="bu">str</span>(here)</span>\n<span id="cb1-26"><a href="#cb1-26" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-27"><a href="#cb1-27" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-28"><a href="#cb1-28" aria-hidden="true" tabindex="-1"></a>sys.path.insert(<span class="dv">0</span>, _course_modules_dir())</span>\n<span id="cb1-29"><a href="#cb1-29" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> variants <span class="im">import</span> get_variant, describe_variant  <span class="co"># noqa: E402</span></span>\n<span id="cb1-30"><a href="#cb1-30" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-31"><a href="#cb1-31" aria-hidden="true" tabindex="-1"></a>RANDOM_STATE <span class="op">=</span> <span class="dv">42</span>          <span class="co"># единый seed на всю работу: результаты воспроизводимы</span></span>\n<span id="cb1-32"><a href="#cb1-32" aria-hidden="true" tabindex="-1"></a>rng <span class="op">=</span> np.random.default_rng(RANDOM_STATE)</span>\n<span id="cb1-33"><a href="#cb1-33" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-34"><a href="#cb1-34" aria-hidden="true" tabindex="-1"></a>plt.rcParams.update({</span>\n<span id="cb1-35"><a href="#cb1-35" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.figsize&quot;</span>: (<span class="fl">7.5</span>, <span class="fl">4.5</span>),</span>\n<span id="cb1-36"><a href="#cb1-36" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.dpi&quot;</span>: <span class="dv">110</span>,</span>\n<span id="cb1-37"><a href="#cb1-37" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.grid&quot;</span>: <span class="va">True</span>,</span>\n<span id="cb1-38"><a href="#cb1-38" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;grid.alpha&quot;</span>: <span class="fl">0.25</span>,</span>\n<span id="cb1-39"><a href="#cb1-39" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.spines.top&quot;</span>: <span class="va">False</span>,</span>\n<span id="cb1-40"><a href="#cb1-40" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.spines.right&quot;</span>: <span class="va">False</span>,</span>\n<span id="cb1-41"><a href="#cb1-41" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;font.size&quot;</span>: <span class="dv">11</span>,</span>\n<span id="cb1-42"><a href="#cb1-42" aria-hidden="true" tabindex="-1"></a>})</span>\n<span id="cb1-43"><a href="#cb1-43" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-44"><a href="#cb1-44" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;numpy&quot;</span>, np.__version__, <span class="st">&quot;| pandas&quot;</span>, pd.__version__)</span>\n<span id="cb1-45"><a href="#cb1-45" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-46"><a href="#cb1-46" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.cluster <span class="im">import</span> AgglomerativeClustering, DBSCAN, KMeans, SpectralClustering</span>\n<span id="cb1-47"><a href="#cb1-47" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.metrics <span class="im">import</span> (adjusted_mutual_info_score, adjusted_rand_score,</span>\n<span id="cb1-48"><a href="#cb1-48" aria-hidden="true" tabindex="-1"></a>                             silhouette_samples, silhouette_score)</span>\n<span id="cb1-49"><a href="#cb1-49" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.mixture <span class="im">import</span> GaussianMixture</span>\n<span id="cb1-50"><a href="#cb1-50" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.datasets <span class="im">import</span> make_blobs, make_circles</span>\n<span id="cb1-51"><a href="#cb1-51" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.preprocessing <span class="im">import</span> StandardScaler</span>\n<span id="cb1-52"><a href="#cb1-52" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> labdata <span class="im">import</span> load_personal</span></code></pre></div>\n</div>\n<div id="cell003" class="cell markdown">\n<h2 id="индивидуальный-вариант">Индивидуальный вариант</h2>\n<p>Впишите своё ФИО (или почту) в переменную <code>STUDENT</code> —\nвариант вычисляется детерминированно, при повторном запуске он тот же\nсамый.</p>\n</div>\n<div id="cell004" class="cell code">\n<div class="sourceCode" id="cb2"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb2-1"><a href="#cb2-1" aria-hidden="true" tabindex="-1"></a>STUDENT <span class="op">=</span> <span class="st">&quot;Фамилия Имя Отчество&quot;</span>   <span class="co"># &lt;-- впишите себя</span></span>\n<span id="cb2-2"><a href="#cb2-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-3"><a href="#cb2-3" aria-hidden="true" tabindex="-1"></a>variant <span class="op">=</span> get_variant(STUDENT, lab<span class="op">=</span><span class="dv">8</span>)</span>\n<span id="cb2-4"><a href="#cb2-4" aria-hidden="true" tabindex="-1"></a>describe_variant(variant)</span></code></pre></div>\n</div>\n<div id="cell005" class="cell markdown">\n<hr />\n<h1 id="часть-1-k-средних-и-его-функционал">Часть 1.\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>K</mi><annotation encoding="application/x-tex">K</annotation></semantics></math>-средних\nи его функционал</h1>\n<p>Определение 7.1: минимизируется сумма квадратов расстояний до\nцентров</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mi>C</mi><mo>,</mo><mi>μ</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><munderover><mo>∑</mo><mrow><mi>k</mi><mo>=</mo><mn>1</mn></mrow><mi>K</mi></munderover><munder><mo>∑</mo><mrow><mi>i</mi><mo>∈</mo><msub><mi>C</mi><mi>k</mi></msub></mrow></munder><mo stretchy="false" form="postfix">∥</mo><msub><mi>x</mi><mi>i</mi></msub><mo>−</mo><msub><mi>μ</mi><mi>k</mi></msub><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup><mspace width="0.278em"></mspace><mo>→</mo><mspace width="0.278em"></mspace><mrow><mi>min</mi><mo>⁡</mo></mrow><mi>.</mi></mrow><annotation encoding="application/x-tex">\nQ(C, \\mu) = \\sum_{k=1}^{K}\\sum_{i \\in C_k}\\|x_i - \\mu_k\\|^2 \\;\\longrightarrow\\; \\min .\n</annotation></semantics></math></p>\n<p>Алгоритм Ллойда чередует два шага, каждый из которых решает свою\nподзадачу <strong>точно</strong>: отнести объект к ближайшему центру и\nпересчитать центры как средние. Поэтому\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>Q</mi><annotation encoding="application/x-tex">Q</annotation></semantics></math>\nне возрастает, и метод сходится за конечное число шагов — но только к\nлокальному минимуму.</p>\n</div>\n<div id="cell006" class="cell code">\n<div class="sourceCode" id="cb3"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb3-1"><a href="#cb3-1" aria-hidden="true" tabindex="-1"></a>X_b, _ <span class="op">=</span> make_blobs(n_samples<span class="op">=</span><span class="dv">500</span>, centers<span class="op">=</span><span class="dv">4</span>, cluster_std<span class="op">=</span><span class="fl">1.1</span>, random_state<span class="op">=</span>RANDOM_STATE)</span>\n<span id="cb3-2"><a href="#cb3-2" aria-hidden="true" tabindex="-1"></a>X_b <span class="op">=</span> StandardScaler().fit_transform(X_b)</span>\n<span id="cb3-3"><a href="#cb3-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-4"><a href="#cb3-4" aria-hidden="true" tabindex="-1"></a>km <span class="op">=</span> KMeans(n_clusters<span class="op">=</span><span class="dv">4</span>, n_init<span class="op">=</span><span class="dv">1</span>, init<span class="op">=</span><span class="st">&quot;random&quot;</span>, random_state<span class="op">=</span>RANDOM_STATE).fit(X_b)</span>\n<span id="cb3-5"><a href="#cb3-5" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;Q (инерция) при одном запуске со случайной инициализацией: </span><span class="sc">{</span>km<span class="sc">.</span>inertia_<span class="sc">:.4f}</span><span class="ss">&quot;</span>)</span>\n<span id="cb3-6"><a href="#cb3-6" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;Q при n_init=10 и k-means++:                              &quot;</span></span>\n<span id="cb3-7"><a href="#cb3-7" aria-hidden="true" tabindex="-1"></a>      <span class="ss">f&quot;</span><span class="sc">{</span>KMeans(n_clusters<span class="op">=</span><span class="dv">4</span>, n_init<span class="op">=</span><span class="dv">10</span>, random_state<span class="op">=</span>RANDOM_STATE)<span class="sc">.</span>fit(X_b)<span class="sc">.</span>inertia_<span class="sc">:.4f}</span><span class="ss">&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell007" class="cell code" data-tags="[&quot;task&quot;,&quot;exercise&quot;]">\n<div class="sourceCode" id="cb4"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb4-1"><a href="#cb4-1" aria-hidden="true" tabindex="-1"></a><span class="co"># ✍ ЗАДАНИЕ НА СЕМИНАРЕ — допишите эту ячейку</span></span>\n<span id="cb4-2"><a href="#cb4-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-3"><a href="#cb4-3" aria-hidden="true" tabindex="-1"></a>res <span class="op">=</span> {<span class="st">&quot;случайная&quot;</span>: [], <span class="st">&quot;k-means++&quot;</span>: []}</span>\n<span id="cb4-4"><a href="#cb4-4" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co"> (3-4 строки): по 60 запусков KMeans(4, n_init=1) с init=&quot;random&quot;</span></span>\n<span id="cb4-5"><a href="#cb4-5" aria-hidden="true" tabindex="-1"></a><span class="co">#   и init=&quot;k-means++&quot; (меняйте random_state), собирайте .inertia_.</span></span>\n<span id="cb4-6"><a href="#cb4-6" aria-hidden="true" tabindex="-1"></a><span class="co">#   Затем для каждой инициализации выведите лучшее Q, среднее Q и долю</span></span>\n<span id="cb4-7"><a href="#cb4-7" aria-hidden="true" tabindex="-1"></a><span class="co">#   запусков, попавших в лучший минимум (в пределах 1 %).</span></span></code></pre></div>\n</div>\n<div id="cell008" class="cell code">\n<div class="sourceCode" id="cb5"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb5-1"><a href="#cb5-1" aria-hidden="true" tabindex="-1"></a>fig, ax <span class="op">=</span> plt.subplots()</span>\n<span id="cb5-2"><a href="#cb5-2" aria-hidden="true" tabindex="-1"></a>ax.hist([res[<span class="st">&quot;случайная&quot;</span>], res[<span class="st">&quot;k-means++&quot;</span>]], bins<span class="op">=</span><span class="dv">25</span>, label<span class="op">=</span>[<span class="st">&quot;случайная&quot;</span>, <span class="st">&quot;k-means++&quot;</span>])</span>\n<span id="cb5-3"><a href="#cb5-3" aria-hidden="true" tabindex="-1"></a>ax.set_xlabel(<span class="st">&quot;итоговое $Q$&quot;</span>)<span class="op">;</span> ax.set_ylabel(<span class="st">&quot;число запусков&quot;</span>)<span class="op">;</span> ax.legend()</span>\n<span id="cb5-4"><a href="#cb5-4" aria-hidden="true" tabindex="-1"></a>ax.set_title(<span class="st">&quot;60 запусков: качество локального минимума&quot;</span>)</span>\n<span id="cb5-5"><a href="#cb5-5" aria-hidden="true" tabindex="-1"></a>plt.tight_layout()<span class="op">;</span> plt.show()</span></code></pre></div>\n</div>\n<div id="cell009" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Какая инициализация чаще попадает в хороший\nминимум и почему? Зачем в <code>sklearn</code> параметр\n<code>n_init</code>?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell010" class="cell markdown">\n<hr />\n<h1 id="часть-2-чего-k-средних-не-умеет--и-почему">Часть 2. Чего\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>K</mi><annotation encoding="application/x-tex">K</annotation></semantics></math>-средних\nне умеет — и почему</h1>\n<p>Функционал\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mo>∑</mo><mi>k</mi></msub><msub><mo>∑</mo><mrow><mi>i</mi><mo>∈</mo><msub><mi>C</mi><mi>k</mi></msub></mrow></msub><mo stretchy="false" form="postfix">∥</mo><msub><mi>x</mi><mi>i</mi></msub><mo>−</mo><msub><mi>μ</mi><mi>k</mi></msub><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">\\sum_k\\sum_{i\\in C_k}\\|x_i-\\mu_k\\|^2</annotation></semantics></math>\nжёстко задаёт форму кластеров. Разбиение по ближайшему центру — это\n<strong>диаграмма Вороного</strong>, то есть кластеры всегда выпуклые и\nразделены гиперплоскостями. Кроме того, квадрат расстояния штрафует\nкрупные кластеры сильнее мелких.</p>\n<p>Трудный случай берётся из вашего варианта:\n<code>variant[&quot;hard_case&quot;]</code>.</p>\n</div>\n<div id="cell011" class="cell code">\n<div class="sourceCode" id="cb6"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb6-1"><a href="#cb6-1" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> make_hard(case, n<span class="op">=</span><span class="dv">600</span>, seed<span class="op">=</span>RANDOM_STATE):</span>\n<span id="cb6-2"><a href="#cb6-2" aria-hidden="true" tabindex="-1"></a>    g <span class="op">=</span> np.random.default_rng(seed)</span>\n<span id="cb6-3"><a href="#cb6-3" aria-hidden="true" tabindex="-1"></a>    <span class="cf">if</span> case.startswith(<span class="st">&quot;кластеры разного размера&quot;</span>):</span>\n<span id="cb6-4"><a href="#cb6-4" aria-hidden="true" tabindex="-1"></a>        X <span class="op">=</span> np.vstack([g.normal([<span class="dv">0</span>, <span class="dv">0</span>], <span class="fl">0.35</span>, (n <span class="op">//</span> <span class="dv">10</span>, <span class="dv">2</span>)),</span>\n<span id="cb6-5"><a href="#cb6-5" aria-hidden="true" tabindex="-1"></a>                       g.normal([<span class="dv">3</span>, <span class="dv">0</span>], <span class="fl">0.35</span>, (n <span class="op">//</span> <span class="dv">10</span>, <span class="dv">2</span>)),</span>\n<span id="cb6-6"><a href="#cb6-6" aria-hidden="true" tabindex="-1"></a>                       g.normal([<span class="fl">1.5</span>, <span class="fl">3.5</span>], <span class="fl">1.6</span>, (<span class="dv">8</span> <span class="op">*</span> n <span class="op">//</span> <span class="dv">10</span>, <span class="dv">2</span>))])</span>\n<span id="cb6-7"><a href="#cb6-7" aria-hidden="true" tabindex="-1"></a>        y <span class="op">=</span> np.r_[np.zeros(n <span class="op">//</span> <span class="dv">10</span>), np.ones(n <span class="op">//</span> <span class="dv">10</span>), np.full(<span class="dv">8</span> <span class="op">*</span> n <span class="op">//</span> <span class="dv">10</span>, <span class="dv">2</span>)]</span>\n<span id="cb6-8"><a href="#cb6-8" aria-hidden="true" tabindex="-1"></a>    <span class="cf">elif</span> case.startswith(<span class="st">&quot;анизотропные&quot;</span>):</span>\n<span id="cb6-9"><a href="#cb6-9" aria-hidden="true" tabindex="-1"></a>        X, y <span class="op">=</span> make_blobs(n_samples<span class="op">=</span>n, centers<span class="op">=</span><span class="dv">3</span>, cluster_std<span class="op">=</span><span class="fl">0.9</span>, random_state<span class="op">=</span>seed)</span>\n<span id="cb6-10"><a href="#cb6-10" aria-hidden="true" tabindex="-1"></a>        X <span class="op">=</span> X <span class="op">@</span> np.array([[<span class="fl">0.6</span>, <span class="op">-</span><span class="fl">0.63</span>], [<span class="op">-</span><span class="fl">0.41</span>, <span class="fl">0.85</span>]])       <span class="co"># вытягиваем кластеры</span></span>\n<span id="cb6-11"><a href="#cb6-11" aria-hidden="true" tabindex="-1"></a>    <span class="cf">elif</span> case.startswith(<span class="st">&quot;кластеры разной плотности&quot;</span>):</span>\n<span id="cb6-12"><a href="#cb6-12" aria-hidden="true" tabindex="-1"></a>        X <span class="op">=</span> np.vstack([g.normal([<span class="dv">0</span>, <span class="dv">0</span>], <span class="fl">0.25</span>, (n <span class="op">//</span> <span class="dv">3</span>, <span class="dv">2</span>)),</span>\n<span id="cb6-13"><a href="#cb6-13" aria-hidden="true" tabindex="-1"></a>                       g.normal([<span class="fl">2.5</span>, <span class="dv">0</span>], <span class="fl">0.9</span>, (n <span class="op">//</span> <span class="dv">3</span>, <span class="dv">2</span>)),</span>\n<span id="cb6-14"><a href="#cb6-14" aria-hidden="true" tabindex="-1"></a>                       g.normal([<span class="fl">1.2</span>, <span class="fl">3.0</span>], <span class="fl">1.8</span>, (n <span class="op">//</span> <span class="dv">3</span>, <span class="dv">2</span>))])</span>\n<span id="cb6-15"><a href="#cb6-15" aria-hidden="true" tabindex="-1"></a>        y <span class="op">=</span> np.repeat([<span class="dv">0</span>, <span class="dv">1</span>, <span class="dv">2</span>], n <span class="op">//</span> <span class="dv">3</span>)</span>\n<span id="cb6-16"><a href="#cb6-16" aria-hidden="true" tabindex="-1"></a>    <span class="cf">else</span>:                                                     <span class="co"># вложенные кольца</span></span>\n<span id="cb6-17"><a href="#cb6-17" aria-hidden="true" tabindex="-1"></a>        X, y <span class="op">=</span> make_circles(n_samples<span class="op">=</span>n, noise<span class="op">=</span><span class="fl">0.06</span>, factor<span class="op">=</span><span class="fl">0.45</span>, random_state<span class="op">=</span>seed)</span>\n<span id="cb6-18"><a href="#cb6-18" aria-hidden="true" tabindex="-1"></a>    <span class="cf">return</span> StandardScaler().fit_transform(X), np.asarray(y, <span class="bu">int</span>)</span>\n<span id="cb6-19"><a href="#cb6-19" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-20"><a href="#cb6-20" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-21"><a href="#cb6-21" aria-hidden="true" tabindex="-1"></a>case <span class="op">=</span> variant[<span class="st">&quot;hard_case&quot;</span>]</span>\n<span id="cb6-22"><a href="#cb6-22" aria-hidden="true" tabindex="-1"></a>X_h, y_h <span class="op">=</span> make_hard(case)</span>\n<span id="cb6-23"><a href="#cb6-23" aria-hidden="true" tabindex="-1"></a>K_true <span class="op">=</span> <span class="bu">len</span>(np.unique(y_h))</span>\n<span id="cb6-24"><a href="#cb6-24" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;трудный случай вашего варианта: </span><span class="sc">{</span>case<span class="sc">}</span><span class="ss"> (истинных кластеров </span><span class="sc">{</span>K_true<span class="sc">}</span><span class="ss">)&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell012" class="cell code">\n<div class="sourceCode" id="cb7"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb7-1"><a href="#cb7-1" aria-hidden="true" tabindex="-1"></a>methods <span class="op">=</span> {</span>\n<span id="cb7-2"><a href="#cb7-2" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;K-средних&quot;</span>: <span class="kw">lambda</span> X: KMeans(K_true, n_init<span class="op">=</span><span class="dv">10</span>, random_state<span class="op">=</span><span class="dv">0</span>).fit_predict(X),</span>\n<span id="cb7-3"><a href="#cb7-3" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;иерархическая (ward)&quot;</span>: <span class="kw">lambda</span> X: AgglomerativeClustering(K_true, linkage<span class="op">=</span><span class="st">&quot;ward&quot;</span>).fit_predict(X),</span>\n<span id="cb7-4"><a href="#cb7-4" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;иерархическая (single)&quot;</span>: <span class="kw">lambda</span> X: AgglomerativeClustering(K_true, linkage<span class="op">=</span><span class="st">&quot;single&quot;</span>).fit_predict(X),</span>\n<span id="cb7-5"><a href="#cb7-5" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;DBSCAN&quot;</span>: <span class="kw">lambda</span> X: DBSCAN(eps<span class="op">=</span><span class="fl">0.3</span>, min_samples<span class="op">=</span><span class="dv">8</span>).fit_predict(X),</span>\n<span id="cb7-6"><a href="#cb7-6" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;спектральная&quot;</span>: <span class="kw">lambda</span> X: SpectralClustering(K_true, affinity<span class="op">=</span><span class="st">&quot;nearest_neighbors&quot;</span>,</span>\n<span id="cb7-7"><a href="#cb7-7" aria-hidden="true" tabindex="-1"></a>                                                 random_state<span class="op">=</span><span class="dv">0</span>).fit_predict(X),</span>\n<span id="cb7-8"><a href="#cb7-8" aria-hidden="true" tabindex="-1"></a>}</span>\n<span id="cb7-9"><a href="#cb7-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb7-10"><a href="#cb7-10" aria-hidden="true" tabindex="-1"></a>fig, axes <span class="op">=</span> plt.subplots(<span class="dv">1</span>, <span class="bu">len</span>(methods) <span class="op">+</span> <span class="dv">1</span>, figsize<span class="op">=</span>(<span class="fl">3.3</span> <span class="op">*</span> (<span class="bu">len</span>(methods) <span class="op">+</span> <span class="dv">1</span>), <span class="fl">3.6</span>))</span>\n<span id="cb7-11"><a href="#cb7-11" aria-hidden="true" tabindex="-1"></a>axes[<span class="dv">0</span>].scatter(<span class="op">*</span>X_h.T, c<span class="op">=</span>y_h, s<span class="op">=</span><span class="dv">10</span>, cmap<span class="op">=</span><span class="st">&quot;viridis&quot;</span>)</span>\n<span id="cb7-12"><a href="#cb7-12" aria-hidden="true" tabindex="-1"></a>axes[<span class="dv">0</span>].set_title(<span class="st">&quot;истинные классы&quot;</span>, fontsize<span class="op">=</span><span class="dv">9</span>)<span class="op">;</span> axes[<span class="dv">0</span>].set_xticks([])<span class="op">;</span> axes[<span class="dv">0</span>].set_yticks([])</span>\n<span id="cb7-13"><a href="#cb7-13" aria-hidden="true" tabindex="-1"></a>rows <span class="op">=</span> []</span>\n<span id="cb7-14"><a href="#cb7-14" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> ax, (nm, fn) <span class="kw">in</span> <span class="bu">zip</span>(axes[<span class="dv">1</span>:], methods.items()):</span>\n<span id="cb7-15"><a href="#cb7-15" aria-hidden="true" tabindex="-1"></a>    lab <span class="op">=</span> fn(X_h)</span>\n<span id="cb7-16"><a href="#cb7-16" aria-hidden="true" tabindex="-1"></a>    ax.scatter(<span class="op">*</span>X_h.T, c<span class="op">=</span>lab, s<span class="op">=</span><span class="dv">10</span>, cmap<span class="op">=</span><span class="st">&quot;viridis&quot;</span>)</span>\n<span id="cb7-17"><a href="#cb7-17" aria-hidden="true" tabindex="-1"></a>    ax.set_title(<span class="ss">f&quot;</span><span class="sc">{</span>nm<span class="sc">}</span><span class="ch">\\n</span><span class="ss">ARI = </span><span class="sc">{</span>adjusted_rand_score(y_h, lab)<span class="sc">:.3f}</span><span class="ss">&quot;</span>, fontsize<span class="op">=</span><span class="dv">9</span>)</span>\n<span id="cb7-18"><a href="#cb7-18" aria-hidden="true" tabindex="-1"></a>    ax.set_xticks([])<span class="op">;</span> ax.set_yticks([])</span>\n<span id="cb7-19"><a href="#cb7-19" aria-hidden="true" tabindex="-1"></a>    rows.append({<span class="st">&quot;метод&quot;</span>: nm, <span class="st">&quot;ARI&quot;</span>: adjusted_rand_score(y_h, lab),</span>\n<span id="cb7-20"><a href="#cb7-20" aria-hidden="true" tabindex="-1"></a>                 <span class="st">&quot;AMI&quot;</span>: adjusted_mutual_info_score(y_h, lab),</span>\n<span id="cb7-21"><a href="#cb7-21" aria-hidden="true" tabindex="-1"></a>                 <span class="st">&quot;кластеров найдено&quot;</span>: <span class="bu">len</span>(<span class="bu">set</span>(lab) <span class="op">-</span> {<span class="op">-</span><span class="dv">1</span>})})</span>\n<span id="cb7-22"><a href="#cb7-22" aria-hidden="true" tabindex="-1"></a>plt.tight_layout()<span class="op">;</span> plt.show()</span>\n<span id="cb7-23"><a href="#cb7-23" aria-hidden="true" tabindex="-1"></a>display(pd.DataFrame(rows).set_index(<span class="st">&quot;метод&quot;</span>).<span class="bu">round</span>(<span class="dv">3</span>))</span></code></pre></div>\n</div>\n<div id="cell013" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Насколько плохо сработал\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>K</mi><annotation encoding="application/x-tex">K</annotation></semantics></math>-средних\nна вашем случае и <strong>почему именно</strong> — какое свойство\nфункционала это объясняет? Кто справился и за счёт чего?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell014" class="cell markdown">\n<hr />\n<h1 id="часть-3-смеси-распределений-и-em">Часть 3. Смеси распределений и\nEM</h1>\n<p>Определение 7.4: плотность смеси\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>p</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><msub><mo>∑</mo><mi>k</mi></msub><msub><mi>w</mi><mi>k</mi></msub><mspace width="0.167em"></mspace><msub><mi>p</mi><mi>k</mi></msub><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">p(x) = \\sum_k w_k\\,p_k(x)</annotation></semantics></math>.\nПрямая максимизация правдоподобия сложна из-за логарифма суммы; EM (опр.\n7.6) вводит скрытые переменные и чередует:</p>\n<p><strong>E-шаг</strong> — ответственности (опр. 7.8):\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>γ</mi><mrow><mi>i</mi><mi>k</mi></mrow></msub><mo>=</mo><mstyle displaystyle="true"><mfrac><mrow><msub><mi>w</mi><mi>k</mi></msub><mspace width="0.167em"></mspace><msub><mi>p</mi><mi>k</mi></msub><mo stretchy="false" form="prefix">(</mo><msub><mi>x</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo></mrow><mrow><msub><mo>∑</mo><mi>s</mi></msub><msub><mi>w</mi><mi>s</mi></msub><mspace width="0.167em"></mspace><msub><mi>p</mi><mi>s</mi></msub><mo stretchy="false" form="prefix">(</mo><msub><mi>x</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo></mrow></mfrac></mstyle></mrow><annotation encoding="application/x-tex">\\gamma_{ik} = \\dfrac{w_k\\,p_k(x_i)}{\\sum_s w_s\\,p_s(x_i)}</annotation></semantics></math>;</p>\n<p><strong>M-шаг</strong> — пересчёт параметров как\n<strong>взвешенных</strong> оценок с весами\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>γ</mi><mrow><mi>i</mi><mi>k</mi></mrow></msub><annotation encoding="application/x-tex">\\gamma_{ik}</annotation></semantics></math>.</p>\n<p>Теорема 7.7: логарифм правдоподобия <strong>не убывает</strong> на\nкаждой итерации. Проверим — это главный эксперимент занятия.</p>\n</div>\n<div id="cell015" class="cell code">\n<div class="sourceCode" id="cb8"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb8-1"><a href="#cb8-1" aria-hidden="true" tabindex="-1"></a>X_g, _ <span class="op">=</span> make_blobs(n_samples<span class="op">=</span><span class="dv">600</span>, centers<span class="op">=</span><span class="dv">3</span>, cluster_std<span class="op">=</span><span class="fl">1.0</span>, random_state<span class="op">=</span>RANDOM_STATE)</span>\n<span id="cb8-2"><a href="#cb8-2" aria-hidden="true" tabindex="-1"></a>X_g <span class="op">=</span> X_g <span class="op">@</span> np.array([[<span class="fl">0.6</span>, <span class="op">-</span><span class="fl">0.6</span>], [<span class="op">-</span><span class="fl">0.4</span>, <span class="fl">0.8</span>]])      <span class="co"># делаем кластеры вытянутыми</span></span>\n<span id="cb8-3"><a href="#cb8-3" aria-hidden="true" tabindex="-1"></a>X_g <span class="op">=</span> StandardScaler().fit_transform(X_g)</span>\n<span id="cb8-4"><a href="#cb8-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-5"><a href="#cb8-5" aria-hidden="true" tabindex="-1"></a>cov_type <span class="op">=</span> variant[<span class="st">&quot;gmm_cov&quot;</span>]</span>\n<span id="cb8-6"><a href="#cb8-6" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;тип ковариации вашего варианта: </span><span class="sc">{</span>cov_type<span class="sc">}</span><span class="ss">&quot;</span>)</span>\n<span id="cb8-7"><a href="#cb8-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-8"><a href="#cb8-8" aria-hidden="true" tabindex="-1"></a><span class="co"># warm_start + max_iter=1 позволяет проследить logL по шагам</span></span>\n<span id="cb8-9"><a href="#cb8-9" aria-hidden="true" tabindex="-1"></a>gm <span class="op">=</span> GaussianMixture(<span class="dv">3</span>, covariance_type<span class="op">=</span>cov_type, max_iter<span class="op">=</span><span class="dv">1</span>, warm_start<span class="op">=</span><span class="va">True</span>,</span>\n<span id="cb8-10"><a href="#cb8-10" aria-hidden="true" tabindex="-1"></a>                     random_state<span class="op">=</span>RANDOM_STATE, init_params<span class="op">=</span><span class="st">&quot;k-means++&quot;</span>)</span>\n<span id="cb8-11"><a href="#cb8-11" aria-hidden="true" tabindex="-1"></a>logL <span class="op">=</span> []</span>\n<span id="cb8-12"><a href="#cb8-12" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> _ <span class="kw">in</span> <span class="bu">range</span>(<span class="dv">60</span>):</span>\n<span id="cb8-13"><a href="#cb8-13" aria-hidden="true" tabindex="-1"></a>    gm.fit(X_g)</span>\n<span id="cb8-14"><a href="#cb8-14" aria-hidden="true" tabindex="-1"></a>    logL.append(gm.score(X_g) <span class="op">*</span> <span class="bu">len</span>(X_g))</span>\n<span id="cb8-15"><a href="#cb8-15" aria-hidden="true" tabindex="-1"></a>logL <span class="op">=</span> np.array(logL)</span></code></pre></div>\n</div>\n<div id="cell016" class="cell code" data-tags="[&quot;task&quot;,&quot;exercise&quot;]">\n<div class="sourceCode" id="cb9"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb9-1"><a href="#cb9-1" aria-hidden="true" tabindex="-1"></a><span class="co"># ✍ ЗАДАНИЕ НА СЕМИНАРЕ — допишите эту ячейку</span></span>\n<span id="cb9-2"><a href="#cb9-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-3"><a href="#cb9-3" aria-hidden="true" tabindex="-1"></a><span class="co"># logL -- массив значений логарифма правдоподобия по итерациям EM</span></span>\n<span id="cb9-4"><a href="#cb9-4" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co"> (2-3 строки): посчитайте приросты за шаг (np.diff), выведите минимальный</span></span>\n<span id="cb9-5"><a href="#cb9-5" aria-hidden="true" tabindex="-1"></a><span class="co">#   и проверьте, что он неотрицателен -- это и есть теорема 7.7.</span></span></code></pre></div>\n</div>\n<div id="cell017" class="cell code">\n<div class="sourceCode" id="cb10"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb10-1"><a href="#cb10-1" aria-hidden="true" tabindex="-1"></a>gm_full <span class="op">=</span> GaussianMixture(<span class="dv">3</span>, covariance_type<span class="op">=</span>cov_type, n_init<span class="op">=</span><span class="dv">5</span>,</span>\n<span id="cb10-2"><a href="#cb10-2" aria-hidden="true" tabindex="-1"></a>                          random_state<span class="op">=</span>RANDOM_STATE).fit(X_g)</span>\n<span id="cb10-3"><a href="#cb10-3" aria-hidden="true" tabindex="-1"></a>gamma <span class="op">=</span> gm_full.predict_proba(X_g)</span>\n<span id="cb10-4"><a href="#cb10-4" aria-hidden="true" tabindex="-1"></a>labels <span class="op">=</span> gamma.argmax(axis<span class="op">=</span><span class="dv">1</span>)</span>\n<span id="cb10-5"><a href="#cb10-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb10-6"><a href="#cb10-6" aria-hidden="true" tabindex="-1"></a>fig, (ax1, ax2) <span class="op">=</span> plt.subplots(<span class="dv">1</span>, <span class="dv">2</span>, figsize<span class="op">=</span>(<span class="dv">12</span>, <span class="fl">4.6</span>))</span>\n<span id="cb10-7"><a href="#cb10-7" aria-hidden="true" tabindex="-1"></a>ax1.plot(logL, <span class="st">&quot;o-&quot;</span>, lw<span class="op">=</span><span class="dv">2</span>, ms<span class="op">=</span><span class="dv">3</span>)</span>\n<span id="cb10-8"><a href="#cb10-8" aria-hidden="true" tabindex="-1"></a>ax1.set_xlabel(<span class="st">&quot;итерация EM&quot;</span>)<span class="op">;</span> ax1.set_ylabel(<span class="vs">r&quot;</span><span class="dv">$</span><span class="er">\\</span><span class="vs">ln L</span><span class="dv">$</span><span class="vs">&quot;</span>)</span>\n<span id="cb10-9"><a href="#cb10-9" aria-hidden="true" tabindex="-1"></a>ax1.set_title(<span class="st">&quot;Теорема 7.7: правдоподобие не убывает&quot;</span>)</span>\n<span id="cb10-10"><a href="#cb10-10" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb10-11"><a href="#cb10-11" aria-hidden="true" tabindex="-1"></a>ax2.scatter(<span class="op">*</span>X_g.T, c<span class="op">=</span>labels, s<span class="op">=</span><span class="dv">18</span>, cmap<span class="op">=</span><span class="st">&quot;viridis&quot;</span>, alpha<span class="op">=</span>np.clip(gamma.<span class="bu">max</span>(<span class="dv">1</span>), <span class="fl">.25</span>, <span class="dv">1</span>))</span>\n<span id="cb10-12"><a href="#cb10-12" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> k <span class="kw">in</span> <span class="bu">range</span>(<span class="dv">3</span>):</span>\n<span id="cb10-13"><a href="#cb10-13" aria-hidden="true" tabindex="-1"></a>    cov <span class="op">=</span> (gm_full.covariances_[k] <span class="cf">if</span> cov_type <span class="op">==</span> <span class="st">&quot;full&quot;</span> <span class="cf">else</span></span>\n<span id="cb10-14"><a href="#cb10-14" aria-hidden="true" tabindex="-1"></a>           np.diag(gm_full.covariances_[k]) <span class="cf">if</span> cov_type <span class="op">==</span> <span class="st">&quot;diag&quot;</span> <span class="cf">else</span></span>\n<span id="cb10-15"><a href="#cb10-15" aria-hidden="true" tabindex="-1"></a>           np.eye(<span class="dv">2</span>) <span class="op">*</span> gm_full.covariances_[k])</span>\n<span id="cb10-16"><a href="#cb10-16" aria-hidden="true" tabindex="-1"></a>    vals, vecs <span class="op">=</span> np.linalg.eigh(cov)</span>\n<span id="cb10-17"><a href="#cb10-17" aria-hidden="true" tabindex="-1"></a>    ang <span class="op">=</span> np.degrees(np.arctan2(vecs[<span class="dv">1</span>, <span class="op">-</span><span class="dv">1</span>], vecs[<span class="dv">0</span>, <span class="op">-</span><span class="dv">1</span>]))</span>\n<span id="cb10-18"><a href="#cb10-18" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> s <span class="kw">in</span> (<span class="dv">1</span>, <span class="dv">2</span>):</span>\n<span id="cb10-19"><a href="#cb10-19" aria-hidden="true" tabindex="-1"></a>        ax2.add_patch(plt.matplotlib.patches.Ellipse(</span>\n<span id="cb10-20"><a href="#cb10-20" aria-hidden="true" tabindex="-1"></a>            gm_full.means_[k], <span class="op">*</span>(<span class="dv">2</span> <span class="op">*</span> s <span class="op">*</span> np.sqrt(vals[::<span class="op">-</span><span class="dv">1</span>])), angle<span class="op">=</span>ang,</span>\n<span id="cb10-21"><a href="#cb10-21" aria-hidden="true" tabindex="-1"></a>            fill<span class="op">=</span><span class="va">False</span>, lw<span class="op">=</span><span class="fl">1.6</span>, color<span class="op">=</span><span class="st">&quot;black&quot;</span>))</span>\n<span id="cb10-22"><a href="#cb10-22" aria-hidden="true" tabindex="-1"></a>ax2.set_title(<span class="st">&quot;Компоненты смеси (прозрачность = неуверенность)&quot;</span>)</span>\n<span id="cb10-23"><a href="#cb10-23" aria-hidden="true" tabindex="-1"></a>plt.tight_layout()<span class="op">;</span> plt.show()</span></code></pre></div>\n</div>\n<div id="cell018" class="cell markdown">\n<h3 id="k-средних-как-предельный-случай-em"><math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>K</mi><annotation encoding="application/x-tex">K</annotation></semantics></math>-средних\nкак предельный случай EM</h3>\n<p>Возьмём сферические ковариации\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi mathvariant="normal">Σ</mi><mi>k</mi></msub><mo>=</mo><msup><mi>σ</mi><mn>2</mn></msup><mi>I</mi></mrow><annotation encoding="application/x-tex">\\Sigma_k = \\sigma^2 I</annotation></semantics></math>\nи устремим\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>σ</mi><mo>→</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">\\sigma\\to0</annotation></semantics></math>.\nОтветственности\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>γ</mi><mrow><mi>i</mi><mi>k</mi></mrow></msub><mo>∝</mo><msub><mi>w</mi><mi>k</mi></msub><mrow><mi>exp</mi><mo>⁡</mo></mrow><mo minsize="120%" maxsize="120%" stretchy="true" form="prefix">(</mo><mi>−</mi><mo stretchy="false" form="postfix">∥</mo><msub><mi>x</mi><mi>i</mi></msub><mo>−</mo><msub><mi>μ</mi><mi>k</mi></msub><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup><mi>/</mi><mo stretchy="false" form="prefix">(</mo><mn>2</mn><msup><mi>σ</mi><mn>2</mn></msup><mo stretchy="false" form="postfix">)</mo><mo minsize="120%" maxsize="120%" stretchy="true" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\gamma_{ik} \\propto w_k\\exp\\bigl(-\\|x_i-\\mu_k\\|^2/(2\\sigma^2)\\bigr)</annotation></semantics></math>\nпревращаются в жёсткое отнесение к ближайшему центру, а M-шаг — в\nпересчёт средних. То есть\n<strong><math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>K</mi><annotation encoding="application/x-tex">K</annotation></semantics></math>-средних\n— это EM для сферической смеси при\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>σ</mi><mo>→</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">\\sigma\\to0</annotation></semantics></math></strong>.</p>\n</div>\n<div id="cell019" class="cell code">\n<div class="sourceCode" id="cb11"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb11-1"><a href="#cb11-1" aria-hidden="true" tabindex="-1"></a>km3 <span class="op">=</span> KMeans(<span class="dv">3</span>, n_init<span class="op">=</span><span class="dv">10</span>, random_state<span class="op">=</span>RANDOM_STATE).fit(X_g)</span>\n<span id="cb11-2"><a href="#cb11-2" aria-hidden="true" tabindex="-1"></a>d2 <span class="op">=</span> ((X_g[:, <span class="va">None</span>, :] <span class="op">-</span> km3.cluster_centers_[<span class="va">None</span>, :, :]) <span class="op">**</span> <span class="dv">2</span>).<span class="bu">sum</span>(<span class="op">-</span><span class="dv">1</span>)</span>\n<span id="cb11-3"><a href="#cb11-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb11-4"><a href="#cb11-4" aria-hidden="true" tabindex="-1"></a>rows <span class="op">=</span> []</span>\n<span id="cb11-5"><a href="#cb11-5" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> sigma <span class="kw">in</span> [<span class="fl">1.0</span>, <span class="fl">0.5</span>, <span class="fl">0.2</span>, <span class="fl">0.1</span>, <span class="fl">0.05</span>, <span class="fl">0.02</span>]:</span>\n<span id="cb11-6"><a href="#cb11-6" aria-hidden="true" tabindex="-1"></a>    logg <span class="op">=</span> <span class="op">-</span>d2 <span class="op">/</span> (<span class="dv">2</span> <span class="op">*</span> sigma <span class="op">**</span> <span class="dv">2</span>)</span>\n<span id="cb11-7"><a href="#cb11-7" aria-hidden="true" tabindex="-1"></a>    gam <span class="op">=</span> np.exp(logg <span class="op">-</span> logg.<span class="bu">max</span>(axis<span class="op">=</span><span class="dv">1</span>, keepdims<span class="op">=</span><span class="va">True</span>))</span>\n<span id="cb11-8"><a href="#cb11-8" aria-hidden="true" tabindex="-1"></a>    gam <span class="op">/=</span> gam.<span class="bu">sum</span>(axis<span class="op">=</span><span class="dv">1</span>, keepdims<span class="op">=</span><span class="va">True</span>)</span>\n<span id="cb11-9"><a href="#cb11-9" aria-hidden="true" tabindex="-1"></a>    rows.append({<span class="st">&quot;sigma&quot;</span>: sigma, <span class="st">&quot;средняя max-ответственность&quot;</span>: gam.<span class="bu">max</span>(axis<span class="op">=</span><span class="dv">1</span>).mean(),</span>\n<span id="cb11-10"><a href="#cb11-10" aria-hidden="true" tabindex="-1"></a>                 <span class="st">&quot;доля объектов с gamma &gt; 0.99&quot;</span>: np.mean(gam.<span class="bu">max</span>(axis<span class="op">=</span><span class="dv">1</span>) <span class="op">&gt;</span> <span class="fl">0.99</span>),</span>\n<span id="cb11-11"><a href="#cb11-11" aria-hidden="true" tabindex="-1"></a>                 <span class="st">&quot;ARI с K-средних&quot;</span>: adjusted_rand_score(gam.argmax(<span class="dv">1</span>), km3.labels_)})</span>\n<span id="cb11-12"><a href="#cb11-12" aria-hidden="true" tabindex="-1"></a>display(pd.DataFrame(rows).set_index(<span class="st">&quot;sigma&quot;</span>).<span class="bu">round</span>(<span class="dv">4</span>))</span></code></pre></div>\n</div>\n<div id="cell020" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Подтвердилась ли монотонность? Что происходит\nс ответственностями при\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>σ</mi><mo>→</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">\\sigma\\to0</annotation></semantics></math>?\nКогда мягкое отнесение предпочтительнее жёсткого?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell021" class="cell markdown">\n<hr />\n<h1 id="часть-4-сколько-кластеров">Часть 4. Сколько кластеров</h1>\n<p>Меток нет, поэтому «правильное»\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>K</mi><annotation encoding="application/x-tex">K</annotation></semantics></math>\nвыбирается косвенно:</p>\n<ul>\n<li><strong>метод локтя</strong>:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mi>K</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">Q(K)</annotation></semantics></math>\nубывает всегда, ищут точку излома;</li>\n<li><strong>силуэт</strong>:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>s</mi><mi>i</mi></msub><mo>=</mo><mstyle displaystyle="true"><mfrac><mrow><msub><mi>b</mi><mi>i</mi></msub><mo>−</mo><msub><mi>a</mi><mi>i</mi></msub></mrow><mrow><mrow><mi>max</mi><mo>⁡</mo></mrow><mo stretchy="false" form="prefix">(</mo><msub><mi>a</mi><mi>i</mi></msub><mo>,</mo><msub><mi>b</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo></mrow></mfrac></mstyle></mrow><annotation encoding="application/x-tex">s_i = \\dfrac{b_i - a_i}{\\max(a_i, b_i)}</annotation></semantics></math>,\nгде\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>a</mi><mi>i</mi></msub><annotation encoding="application/x-tex">a_i</annotation></semantics></math>\n— среднее расстояние внутри своего кластера,\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>b</mi><mi>i</mi></msub><annotation encoding="application/x-tex">b_i</annotation></semantics></math>\n— до ближайшего чужого;</li>\n<li><strong>информационные критерии</strong> для смеси:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi mathvariant="normal">A</mi><mi mathvariant="normal">I</mi><mi mathvariant="normal">C</mi></mrow><mo>=</mo><mi>−</mi><mn>2</mn><mrow><mi>ln</mi><mo>⁡</mo></mrow><mi>L</mi><mo>+</mo><mn>2</mn><mi>p</mi></mrow><annotation encoding="application/x-tex">\\mathrm{AIC} = -2\\ln L + 2p</annotation></semantics></math>,\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi mathvariant="normal">B</mi><mi mathvariant="normal">I</mi><mi mathvariant="normal">C</mi></mrow><mo>=</mo><mi>−</mi><mn>2</mn><mrow><mi>ln</mi><mo>⁡</mo></mrow><mi>L</mi><mo>+</mo><mi>p</mi><mrow><mi>ln</mi><mo>⁡</mo></mrow><mi>ℓ</mi></mrow><annotation encoding="application/x-tex">\\mathrm{BIC} = -2\\ln L + p\\ln\\ell</annotation></semantics></math>.</li>\n</ul>\n<p>Ваш вариант: <code>variant[&quot;k_selection&quot;]</code>. Проверим на данных\nс известным ответом.</p>\n</div>\n<div id="cell022" class="cell code">\n<div class="sourceCode" id="cb12"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb12-1"><a href="#cb12-1" aria-hidden="true" tabindex="-1"></a>X_k, y_k <span class="op">=</span> make_blobs(n_samples<span class="op">=</span><span class="dv">600</span>, centers<span class="op">=</span><span class="dv">4</span>, cluster_std<span class="op">=</span><span class="fl">1.15</span>, random_state<span class="op">=</span>RANDOM_STATE)</span>\n<span id="cb12-2"><a href="#cb12-2" aria-hidden="true" tabindex="-1"></a>X_k <span class="op">=</span> StandardScaler().fit_transform(X_k)</span>\n<span id="cb12-3"><a href="#cb12-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb12-4"><a href="#cb12-4" aria-hidden="true" tabindex="-1"></a>rows <span class="op">=</span> []</span>\n<span id="cb12-5"><a href="#cb12-5" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> K <span class="kw">in</span> <span class="bu">range</span>(<span class="dv">2</span>, <span class="dv">11</span>):</span>\n<span id="cb12-6"><a href="#cb12-6" aria-hidden="true" tabindex="-1"></a>    km <span class="op">=</span> KMeans(K, n_init<span class="op">=</span><span class="dv">10</span>, random_state<span class="op">=</span>RANDOM_STATE).fit(X_k)</span>\n<span id="cb12-7"><a href="#cb12-7" aria-hidden="true" tabindex="-1"></a>    gm <span class="op">=</span> GaussianMixture(K, covariance_type<span class="op">=</span><span class="st">&quot;full&quot;</span>, random_state<span class="op">=</span>RANDOM_STATE,</span>\n<span id="cb12-8"><a href="#cb12-8" aria-hidden="true" tabindex="-1"></a>                         n_init<span class="op">=</span><span class="dv">3</span>).fit(X_k)</span>\n<span id="cb12-9"><a href="#cb12-9" aria-hidden="true" tabindex="-1"></a>    rows.append({<span class="st">&quot;K&quot;</span>: K, <span class="st">&quot;Q (инерция)&quot;</span>: km.inertia_,</span>\n<span id="cb12-10"><a href="#cb12-10" aria-hidden="true" tabindex="-1"></a>                 <span class="st">&quot;силуэт&quot;</span>: silhouette_score(X_k, km.labels_),</span>\n<span id="cb12-11"><a href="#cb12-11" aria-hidden="true" tabindex="-1"></a>                 <span class="st">&quot;AIC&quot;</span>: gm.aic(X_k), <span class="st">&quot;BIC&quot;</span>: gm.bic(X_k),</span>\n<span id="cb12-12"><a href="#cb12-12" aria-hidden="true" tabindex="-1"></a>                 <span class="st">&quot;ARI с истиной&quot;</span>: adjusted_rand_score(y_k, km.labels_)})</span>\n<span id="cb12-13"><a href="#cb12-13" aria-hidden="true" tabindex="-1"></a>sel <span class="op">=</span> pd.DataFrame(rows).set_index(<span class="st">&quot;K&quot;</span>)</span>\n<span id="cb12-14"><a href="#cb12-14" aria-hidden="true" tabindex="-1"></a>display(sel.<span class="bu">round</span>(<span class="dv">3</span>))</span></code></pre></div>\n</div>\n<div id="cell023" class="cell code">\n<div class="sourceCode" id="cb13"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb13-1"><a href="#cb13-1" aria-hidden="true" tabindex="-1"></a>choices <span class="op">=</span> {</span>\n<span id="cb13-2"><a href="#cb13-2" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;локоть (макс. вторая разность Q)&quot;</span>: <span class="bu">int</span>(sel.index[<span class="dv">1</span> <span class="op">+</span> np.argmax(np.diff(sel[<span class="st">&quot;Q (инерция)&quot;</span>], <span class="dv">2</span>))]),</span>\n<span id="cb13-3"><a href="#cb13-3" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;силуэт&quot;</span>: <span class="bu">int</span>(sel[<span class="st">&quot;силуэт&quot;</span>].idxmax()),</span>\n<span id="cb13-4"><a href="#cb13-4" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;AIC&quot;</span>: <span class="bu">int</span>(sel[<span class="st">&quot;AIC&quot;</span>].idxmin()), <span class="st">&quot;BIC&quot;</span>: <span class="bu">int</span>(sel[<span class="st">&quot;BIC&quot;</span>].idxmin()),</span>\n<span id="cb13-5"><a href="#cb13-5" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;ARI (знание истины)&quot;</span>: <span class="bu">int</span>(sel[<span class="st">&quot;ARI с истиной&quot;</span>].idxmax()),</span>\n<span id="cb13-6"><a href="#cb13-6" aria-hidden="true" tabindex="-1"></a>}</span>\n<span id="cb13-7"><a href="#cb13-7" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;критерии вашего варианта:&quot;</span>, variant[<span class="st">&quot;k_selection&quot;</span>], <span class="st">&quot;</span><span class="ch">\\n</span><span class="st">&quot;</span>)</span>\n<span id="cb13-8"><a href="#cb13-8" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> k, v <span class="kw">in</span> choices.items():</span>\n<span id="cb13-9"><a href="#cb13-9" aria-hidden="true" tabindex="-1"></a>    <span class="bu">print</span>(<span class="ss">f&quot;  </span><span class="sc">{</span>k<span class="sc">:34s}</span><span class="ss"> -&gt; K = </span><span class="sc">{</span>v<span class="sc">}</span><span class="ss">&quot;</span>)</span>\n<span id="cb13-10"><a href="#cb13-10" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb13-11"><a href="#cb13-11" aria-hidden="true" tabindex="-1"></a>fig, axes <span class="op">=</span> plt.subplots(<span class="dv">1</span>, <span class="dv">3</span>, figsize<span class="op">=</span>(<span class="dv">15</span>, <span class="dv">4</span>))</span>\n<span id="cb13-12"><a href="#cb13-12" aria-hidden="true" tabindex="-1"></a>axes[<span class="dv">0</span>].plot(sel.index, sel[<span class="st">&quot;Q (инерция)&quot;</span>], <span class="st">&quot;o-&quot;</span>, lw<span class="op">=</span><span class="dv">2</span>)</span>\n<span id="cb13-13"><a href="#cb13-13" aria-hidden="true" tabindex="-1"></a>axes[<span class="dv">0</span>].set_xlabel(<span class="st">&quot;$K$&quot;</span>)<span class="op">;</span> axes[<span class="dv">0</span>].set_ylabel(<span class="st">&quot;$Q$&quot;</span>)<span class="op">;</span> axes[<span class="dv">0</span>].set_title(<span class="st">&quot;Метод локтя&quot;</span>)</span>\n<span id="cb13-14"><a href="#cb13-14" aria-hidden="true" tabindex="-1"></a>axes[<span class="dv">1</span>].plot(sel.index, sel[<span class="st">&quot;силуэт&quot;</span>], <span class="st">&quot;o-&quot;</span>, lw<span class="op">=</span><span class="dv">2</span>, color<span class="op">=</span><span class="st">&quot;#C97A2B&quot;</span>)</span>\n<span id="cb13-15"><a href="#cb13-15" aria-hidden="true" tabindex="-1"></a>axes[<span class="dv">1</span>].axvline(choices[<span class="st">&quot;силуэт&quot;</span>], ls<span class="op">=</span><span class="st">&quot;--&quot;</span>, color<span class="op">=</span><span class="st">&quot;black&quot;</span>)</span>\n<span id="cb13-16"><a href="#cb13-16" aria-hidden="true" tabindex="-1"></a>axes[<span class="dv">1</span>].set_xlabel(<span class="st">&quot;$K$&quot;</span>)<span class="op">;</span> axes[<span class="dv">1</span>].set_ylabel(<span class="st">&quot;средний силуэт&quot;</span>)<span class="op">;</span> axes[<span class="dv">1</span>].set_title(<span class="st">&quot;Силуэт&quot;</span>)</span>\n<span id="cb13-17"><a href="#cb13-17" aria-hidden="true" tabindex="-1"></a>axes[<span class="dv">2</span>].plot(sel.index, sel[<span class="st">&quot;AIC&quot;</span>], <span class="st">&quot;o-&quot;</span>, lw<span class="op">=</span><span class="dv">2</span>, label<span class="op">=</span><span class="st">&quot;AIC&quot;</span>)</span>\n<span id="cb13-18"><a href="#cb13-18" aria-hidden="true" tabindex="-1"></a>axes[<span class="dv">2</span>].plot(sel.index, sel[<span class="st">&quot;BIC&quot;</span>], <span class="st">&quot;s-&quot;</span>, lw<span class="op">=</span><span class="dv">2</span>, label<span class="op">=</span><span class="st">&quot;BIC&quot;</span>)</span>\n<span id="cb13-19"><a href="#cb13-19" aria-hidden="true" tabindex="-1"></a>axes[<span class="dv">2</span>].set_xlabel(<span class="st">&quot;$K$&quot;</span>)<span class="op">;</span> axes[<span class="dv">2</span>].set_title(<span class="st">&quot;Информационные критерии&quot;</span>)<span class="op">;</span> axes[<span class="dv">2</span>].legend()</span>\n<span id="cb13-20"><a href="#cb13-20" aria-hidden="true" tabindex="-1"></a>plt.tight_layout()<span class="op">;</span> plt.show()</span></code></pre></div>\n</div>\n<div id="cell024" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Совпали ли ответы разных критериев с истинным\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>K</mi><mo>=</mo><mn>4</mn></mrow><annotation encoding="application/x-tex">K=4</annotation></semantics></math>?\nПочему\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mi>K</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">Q(K)</annotation></semantics></math>\nнельзя минимизировать напрямую?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell025" class="cell markdown">\n<hr />\n<h1 id="часть-5-иерархическая-кластеризация-и-эффект-цепочки">Часть 5.\nИерархическая кластеризация и эффект цепочки</h1>\n<p>Определение 7.11: агломеративный алгоритм начинает с\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>ℓ</mi><annotation encoding="application/x-tex">\\ell</annotation></semantics></math>\nодноэлементных кластеров и на каждом шаге объединяет два ближайших.\nСпособ измерения расстояния между кластерами (linkage) определяет всё\nповедение: <code>single</code> берёт минимум по парам,\n<code>complete</code> — максимум, <code>ward</code> — прирост\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>Q</mi><annotation encoding="application/x-tex">Q</annotation></semantics></math>\nпри слиянии.</p>\n<p>Ваш вариант: <code>variant[&quot;linkage&quot;]</code>.</p>\n</div>\n<div id="cell026" class="cell code">\n<div class="sourceCode" id="cb14"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb14-1"><a href="#cb14-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> scipy.cluster.hierarchy <span class="im">import</span> dendrogram, fcluster, linkage <span class="im">as</span> scipy_linkage</span>\n<span id="cb14-2"><a href="#cb14-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb14-3"><a href="#cb14-3" aria-hidden="true" tabindex="-1"></a>X_d, y_d <span class="op">=</span> make_blobs(n_samples<span class="op">=</span><span class="dv">160</span>, centers<span class="op">=</span><span class="dv">3</span>, cluster_std<span class="op">=</span><span class="fl">1.0</span>, random_state<span class="op">=</span>RANDOM_STATE)</span>\n<span id="cb14-4"><a href="#cb14-4" aria-hidden="true" tabindex="-1"></a>X_d <span class="op">=</span> StandardScaler().fit_transform(X_d)</span>\n<span id="cb14-5"><a href="#cb14-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb14-6"><a href="#cb14-6" aria-hidden="true" tabindex="-1"></a>fig, axes <span class="op">=</span> plt.subplots(<span class="dv">2</span>, <span class="dv">4</span>, figsize<span class="op">=</span>(<span class="dv">17</span>, <span class="dv">7</span>))</span>\n<span id="cb14-7"><a href="#cb14-7" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> j, lk <span class="kw">in</span> <span class="bu">enumerate</span>([<span class="st">&quot;single&quot;</span>, <span class="st">&quot;complete&quot;</span>, <span class="st">&quot;average&quot;</span>, <span class="st">&quot;ward&quot;</span>]):</span>\n<span id="cb14-8"><a href="#cb14-8" aria-hidden="true" tabindex="-1"></a>    Z <span class="op">=</span> scipy_linkage(X_d, method<span class="op">=</span>lk)</span>\n<span id="cb14-9"><a href="#cb14-9" aria-hidden="true" tabindex="-1"></a>    dendrogram(Z, ax<span class="op">=</span>axes[<span class="dv">0</span>, j], no_labels<span class="op">=</span><span class="va">True</span>, color_threshold<span class="op">=</span>Z[<span class="op">-</span><span class="dv">2</span>, <span class="dv">2</span>])</span>\n<span id="cb14-10"><a href="#cb14-10" aria-hidden="true" tabindex="-1"></a>    axes[<span class="dv">0</span>, j].set_title(lk <span class="op">+</span> (<span class="st">&quot;  &lt;- ваш вариант&quot;</span> <span class="cf">if</span> lk <span class="op">==</span> variant[<span class="st">&quot;linkage&quot;</span>] <span class="cf">else</span> <span class="st">&quot;&quot;</span>),</span>\n<span id="cb14-11"><a href="#cb14-11" aria-hidden="true" tabindex="-1"></a>                         fontsize<span class="op">=</span><span class="dv">10</span>)</span>\n<span id="cb14-12"><a href="#cb14-12" aria-hidden="true" tabindex="-1"></a>    lab <span class="op">=</span> fcluster(Z, <span class="dv">3</span>, criterion<span class="op">=</span><span class="st">&quot;maxclust&quot;</span>) <span class="op">-</span> <span class="dv">1</span></span>\n<span id="cb14-13"><a href="#cb14-13" aria-hidden="true" tabindex="-1"></a>    axes[<span class="dv">1</span>, j].scatter(<span class="op">*</span>X_d.T, c<span class="op">=</span>lab, s<span class="op">=</span><span class="dv">14</span>, cmap<span class="op">=</span><span class="st">&quot;viridis&quot;</span>)</span>\n<span id="cb14-14"><a href="#cb14-14" aria-hidden="true" tabindex="-1"></a>    axes[<span class="dv">1</span>, j].set_title(<span class="ss">f&quot;ARI = </span><span class="sc">{</span>adjusted_rand_score(y_d, lab)<span class="sc">:.3f}</span><span class="ss">&quot;</span>, fontsize<span class="op">=</span><span class="dv">9</span>)</span>\n<span id="cb14-15"><a href="#cb14-15" aria-hidden="true" tabindex="-1"></a>    axes[<span class="dv">1</span>, j].set_xticks([])<span class="op">;</span> axes[<span class="dv">1</span>, j].set_yticks([])</span>\n<span id="cb14-16"><a href="#cb14-16" aria-hidden="true" tabindex="-1"></a>axes[<span class="dv">0</span>, <span class="dv">0</span>].set_ylabel(<span class="st">&quot;расстояние слияния&quot;</span>)</span>\n<span id="cb14-17"><a href="#cb14-17" aria-hidden="true" tabindex="-1"></a>plt.tight_layout()<span class="op">;</span> plt.show()</span></code></pre></div>\n</div>\n<div id="cell027" class="cell code">\n<div class="sourceCode" id="cb15"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb15-1"><a href="#cb15-1" aria-hidden="true" tabindex="-1"></a><span class="co"># Эффект цепочки: две вытянутые полосы и десяток точек-мостика между ними</span></span>\n<span id="cb15-2"><a href="#cb15-2" aria-hidden="true" tabindex="-1"></a>g <span class="op">=</span> np.random.default_rng(<span class="dv">0</span>)</span>\n<span id="cb15-3"><a href="#cb15-3" aria-hidden="true" tabindex="-1"></a>X_ch <span class="op">=</span> np.vstack([np.column_stack([g.uniform(<span class="op">-</span><span class="dv">3</span>, <span class="dv">3</span>, <span class="dv">90</span>), g.normal(<span class="fl">1.6</span>, <span class="fl">0.12</span>, <span class="dv">90</span>)]),</span>\n<span id="cb15-4"><a href="#cb15-4" aria-hidden="true" tabindex="-1"></a>                  np.column_stack([g.uniform(<span class="op">-</span><span class="dv">3</span>, <span class="dv">3</span>, <span class="dv">90</span>), g.normal(<span class="op">-</span><span class="fl">1.6</span>, <span class="fl">0.12</span>, <span class="dv">90</span>)]),</span>\n<span id="cb15-5"><a href="#cb15-5" aria-hidden="true" tabindex="-1"></a>                  np.column_stack([g.normal(<span class="dv">0</span>, <span class="fl">0.05</span>, <span class="dv">12</span>), g.uniform(<span class="op">-</span><span class="fl">1.5</span>, <span class="fl">1.5</span>, <span class="dv">12</span>)])])</span>\n<span id="cb15-6"><a href="#cb15-6" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb15-7"><a href="#cb15-7" aria-hidden="true" tabindex="-1"></a>fig, axes <span class="op">=</span> plt.subplots(<span class="dv">1</span>, <span class="dv">4</span>, figsize<span class="op">=</span>(<span class="dv">16</span>, <span class="fl">3.6</span>))</span>\n<span id="cb15-8"><a href="#cb15-8" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> ax, lk <span class="kw">in</span> <span class="bu">zip</span>(axes, [<span class="st">&quot;single&quot;</span>, <span class="st">&quot;complete&quot;</span>, <span class="st">&quot;average&quot;</span>, <span class="st">&quot;ward&quot;</span>]):</span>\n<span id="cb15-9"><a href="#cb15-9" aria-hidden="true" tabindex="-1"></a>    lab <span class="op">=</span> fcluster(scipy_linkage(X_ch, method<span class="op">=</span>lk), <span class="dv">2</span>, criterion<span class="op">=</span><span class="st">&quot;maxclust&quot;</span>)</span>\n<span id="cb15-10"><a href="#cb15-10" aria-hidden="true" tabindex="-1"></a>    ax.scatter(<span class="op">*</span>X_ch.T, c<span class="op">=</span>lab, s<span class="op">=</span><span class="dv">12</span>, cmap<span class="op">=</span><span class="st">&quot;coolwarm&quot;</span>)</span>\n<span id="cb15-11"><a href="#cb15-11" aria-hidden="true" tabindex="-1"></a>    ax.set_title(<span class="ss">f&quot;</span><span class="sc">{</span>lk<span class="sc">}</span><span class="ss">: размеры кластеров </span><span class="sc">{</span>np<span class="sc">.</span>bincount(lab)[<span class="dv">1</span>:]<span class="sc">}</span><span class="ss">&quot;</span>, fontsize<span class="op">=</span><span class="dv">9</span>)</span>\n<span id="cb15-12"><a href="#cb15-12" aria-hidden="true" tabindex="-1"></a>    ax.set_xticks([])<span class="op">;</span> ax.set_yticks([])</span>\n<span id="cb15-13"><a href="#cb15-13" aria-hidden="true" tabindex="-1"></a>fig.suptitle(<span class="st">&quot;Эффект цепочки: 12 точек-мостика склеивают две полосы&quot;</span>)</span>\n<span id="cb15-14"><a href="#cb15-14" aria-hidden="true" tabindex="-1"></a>plt.tight_layout()<span class="op">;</span> plt.show()</span></code></pre></div>\n</div>\n<div id="cell028" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Какой linkage пострадал от эффекта цепочки и\nпочему? Когда это свойство оказывается полезным?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell029" class="cell markdown">\n<hr />\n<h1 id="часть-6-своя-выборка">Часть 6. Своя выборка</h1>\n<p>Кластеризуем признаковое описание <strong>без</strong> использования\nцелевой переменной и проверим, связаны ли найденные кластеры с целью.\nЭто типичный разведочный сценарий: кластеры могут отражать сегменты,\nкоторые полезно рассматривать отдельно.</p>\n</div>\n<div id="cell030" class="cell code">\n<div class="sourceCode" id="cb16"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb16-1"><a href="#cb16-1" aria-hidden="true" tabindex="-1"></a>data <span class="op">=</span> load_personal(variant, return_frame<span class="op">=</span><span class="va">True</span>)</span>\n<span id="cb16-2"><a href="#cb16-2" aria-hidden="true" tabindex="-1"></a>Xp <span class="op">=</span> np.vstack([data[<span class="st">&quot;X_train&quot;</span>], data[<span class="st">&quot;X_test&quot;</span>]])</span>\n<span id="cb16-3"><a href="#cb16-3" aria-hidden="true" tabindex="-1"></a>yp <span class="op">=</span> np.r_[data[<span class="st">&quot;y_train&quot;</span>], data[<span class="st">&quot;y_test&quot;</span>]]</span>\n<span id="cb16-4"><a href="#cb16-4" aria-hidden="true" tabindex="-1"></a>target_bin <span class="op">=</span> ((yp <span class="op">&gt;</span> np.median(yp)).astype(<span class="bu">int</span>) <span class="cf">if</span> data[<span class="st">&quot;task&quot;</span>] <span class="op">==</span> <span class="st">&quot;regression&quot;</span></span>\n<span id="cb16-5"><a href="#cb16-5" aria-hidden="true" tabindex="-1"></a>              <span class="cf">else</span> yp.astype(<span class="bu">int</span>))</span>\n<span id="cb16-6"><a href="#cb16-6" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;</span><span class="sc">{</span>data[<span class="st">&#39;domain&#39;</span>]<span class="sc">}</span><span class="ss">: </span><span class="sc">{</span>Xp<span class="sc">.</span>shape[<span class="dv">0</span>]<span class="sc">}</span><span class="ss"> объектов, </span><span class="sc">{</span>Xp<span class="sc">.</span>shape[<span class="dv">1</span>]<span class="sc">}</span><span class="ss"> признаков&quot;</span>)</span>\n<span id="cb16-7"><a href="#cb16-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb16-8"><a href="#cb16-8" aria-hidden="true" tabindex="-1"></a>rows <span class="op">=</span> []</span>\n<span id="cb16-9"><a href="#cb16-9" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> K <span class="kw">in</span> <span class="bu">range</span>(<span class="dv">2</span>, <span class="dv">9</span>):</span>\n<span id="cb16-10"><a href="#cb16-10" aria-hidden="true" tabindex="-1"></a>    km <span class="op">=</span> KMeans(K, n_init<span class="op">=</span><span class="dv">10</span>, random_state<span class="op">=</span>RANDOM_STATE).fit(Xp)</span>\n<span id="cb16-11"><a href="#cb16-11" aria-hidden="true" tabindex="-1"></a>    rows.append({<span class="st">&quot;K&quot;</span>: K, <span class="st">&quot;Q&quot;</span>: km.inertia_, <span class="st">&quot;силуэт&quot;</span>: silhouette_score(Xp, km.labels_),</span>\n<span id="cb16-12"><a href="#cb16-12" aria-hidden="true" tabindex="-1"></a>                 <span class="st">&quot;связь с целью (AMI)&quot;</span>: adjusted_mutual_info_score(target_bin, km.labels_)})</span>\n<span id="cb16-13"><a href="#cb16-13" aria-hidden="true" tabindex="-1"></a>own <span class="op">=</span> pd.DataFrame(rows).set_index(<span class="st">&quot;K&quot;</span>)</span>\n<span id="cb16-14"><a href="#cb16-14" aria-hidden="true" tabindex="-1"></a>display(own.<span class="bu">round</span>(<span class="dv">4</span>))</span></code></pre></div>\n</div>\n<div id="cell031" class="cell code">\n<div class="sourceCode" id="cb17"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb17-1"><a href="#cb17-1" aria-hidden="true" tabindex="-1"></a>K_best <span class="op">=</span> <span class="bu">int</span>(own[<span class="st">&quot;силуэт&quot;</span>].idxmax())</span>\n<span id="cb17-2"><a href="#cb17-2" aria-hidden="true" tabindex="-1"></a>km_best <span class="op">=</span> KMeans(K_best, n_init<span class="op">=</span><span class="dv">10</span>, random_state<span class="op">=</span>RANDOM_STATE).fit(Xp)</span>\n<span id="cb17-3"><a href="#cb17-3" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;выбрано K = </span><span class="sc">{</span>K_best<span class="sc">}</span><span class="ss"> (по силуэту)</span><span class="ch">\\n</span><span class="ss">&quot;</span>)</span>\n<span id="cb17-4"><a href="#cb17-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb17-5"><a href="#cb17-5" aria-hidden="true" tabindex="-1"></a>tab <span class="op">=</span> pd.crosstab(pd.Series(km_best.labels_, name<span class="op">=</span><span class="st">&quot;кластер&quot;</span>),</span>\n<span id="cb17-6"><a href="#cb17-6" aria-hidden="true" tabindex="-1"></a>                  pd.Series(target_bin, name<span class="op">=</span>data[<span class="st">&quot;target&quot;</span>]), normalize<span class="op">=</span><span class="st">&quot;index&quot;</span>)</span>\n<span id="cb17-7"><a href="#cb17-7" aria-hidden="true" tabindex="-1"></a>tab[<span class="st">&quot;размер&quot;</span>] <span class="op">=</span> pd.Series(km_best.labels_).value_counts().sort_index()</span>\n<span id="cb17-8"><a href="#cb17-8" aria-hidden="true" tabindex="-1"></a>display(tab.<span class="bu">round</span>(<span class="dv">3</span>))</span>\n<span id="cb17-9"><a href="#cb17-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb17-10"><a href="#cb17-10" aria-hidden="true" tabindex="-1"></a>centers <span class="op">=</span> pd.DataFrame(km_best.cluster_centers_, columns<span class="op">=</span>data[<span class="st">&quot;feature_names&quot;</span>])</span>\n<span id="cb17-11"><a href="#cb17-11" aria-hidden="true" tabindex="-1"></a>spread <span class="op">=</span> (centers.<span class="bu">max</span>() <span class="op">-</span> centers.<span class="bu">min</span>()).sort_values(ascending<span class="op">=</span><span class="va">False</span>).head(<span class="dv">6</span>)</span>\n<span id="cb17-12"><a href="#cb17-12" aria-hidden="true" tabindex="-1"></a>display(centers[spread.index].<span class="bu">round</span>(<span class="dv">2</span>).T.rename(columns<span class="op">=</span><span class="kw">lambda</span> k: <span class="ss">f&quot;кластер </span><span class="sc">{</span>k<span class="sc">}</span><span class="ss">&quot;</span>))</span></code></pre></div>\n</div>\n<div id="cell032" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Связаны ли найденные кластеры с целевой\nпеременной? Чем они отличаются содержательно и означает ли высокий AMI,\nчто кластеризация «удалась»?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell033" class="cell markdown">\n<h2 id="итоги-занятия">Итоги занятия</h2>\n<p>Ответьте письменно на контрольные вопросы (по 2–4 предложения):</p>\n<ol>\n<li>Почему\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>K</mi><annotation encoding="application/x-tex">K</annotation></semantics></math>-средних\nвсегда сходится, но не обязательно к глобальному минимуму? Приведите\nконфигурацию из четырёх точек и\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>K</mi><mo>=</mo><mn>2</mn></mrow><annotation encoding="application/x-tex">K=2</annotation></semantics></math>,\nгде неудачная инициализация даёт неоптимальный ответ.</li>\n<li>Функционал\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>Q</mi><annotation encoding="application/x-tex">Q</annotation></semantics></math>\nмонотонно убывает по\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>K</mi><annotation encoding="application/x-tex">K</annotation></semantics></math>.\nОзначает ли это, что «чем больше кластеров, тем лучше»? Как правильно\nпоставить вопрос о выборе\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>K</mi><annotation encoding="application/x-tex">K</annotation></semantics></math>?</li>\n<li>Теорема 7.7 гарантирует, что\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi>ln</mi><mo>⁡</mo></mrow><mi>L</mi></mrow><annotation encoding="application/x-tex">\\ln L</annotation></semantics></math>\nне убывает. Гарантирует ли она сходимость к глобальному максимуму? Что\nделают на практике?</li>\n<li>Силуэт указал\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>K</mi><mo>=</mo><mn>2</mn></mrow><annotation encoding="application/x-tex">K=2</annotation></semantics></math>,\nBIC —\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>K</mi><mo>=</mo><mn>5</mn></mrow><annotation encoding="application/x-tex">K=5</annotation></semantics></math>.\nВаши действия?</li>\n</ol>\n<hr />\n<p><strong>Дома:</strong> откройте <code>lab08_homework.ipynb</code> —\nтам две задачи: свой алгоритм Ллойда с k-means++ и свой EM для смеси\nгауссиан.</p>\n</div>\n</body>\n</html>\n'}}]);